<nav class="breadcrumb" aria-label="Breadcrumb"><a href="<?= e(url('/decks')) ?>">My decks</a><?= icon('chevron',14) ?><span><?= e($deck['title']) ?></span></nav>
<header class="page-heading deck-detail-heading"><div><span class="badge badge-purple"><?= e($deck['subject'] ?: 'General') ?></span><h1><?= e($deck['title']) ?><span class="heading-dot">.</span></h1><p><?= e($deck['description'] ?: 'A focused collection of things worth remembering.') ?></p></div><div class="heading-actions"><a href="<?= e(url('/decks/' . ((int) $deck['id']) . '/edit')) ?>" class="btn btn-secondary"><?= icon('edit',17) ?> Edit deck</a><a href="<?= e(url('/decks/' . ((int) $deck['id']) . '/cards/create')) ?>" class="btn btn-primary"><?= icon('plus',18) ?> Add a card</a></div></header>
<section class="deck-overview panel" style="--deck-color: <?= e($deck['color']) ?>"><div class="deck-overview-stats"><div><strong><?= (int) $deck['card_count'] ?></strong><span>Total cards</span></div><div><strong><?= (int) $deck['due_count'] ?></strong><span>Due now</span></div><div><strong><?= (int) $deck['progress'] ?>%</strong><span>Mastered</span></div></div><form method="post" action="<?= e(url('/study/start')) ?>"><?= csrf_field() ?><input type="hidden" name="deck_id" value="<?= (int) $deck['id'] ?>"><input type="hidden" name="mode" value="due"><button class="btn btn-primary" <?= !$deck['due_count'] ? 'disabled' : '' ?>><?= icon('study',18) ?> Study due cards</button></form><form method="post" action="<?= e(url('/study/start')) ?>"><?= csrf_field() ?><input type="hidden" name="deck_id" value="<?= (int) $deck['id'] ?>"><input type="hidden" name="mode" value="practice"><button class="btn btn-secondary" <?= !$deck['card_count'] ? 'disabled' : '' ?>>Practice all cards</button></form></section>
<section class="panel"><div class="panel-heading"><h2>Your flashcards</h2><div class="heading-actions"><a class="text-link" href="<?= e(url('/decks/' . ((int) $deck['id']) . '/import')) ?>"><?= icon('upload',16) ?> Import CSV</a><a class="text-link" href="<?= e(url('/decks/' . ((int) $deck['id']) . '/export')) ?>"><?= icon('download',16) ?> Export CSV</a></div></div><form method="get" action="<?= e(url('/decks/' . ((int) $deck['id']))) ?>" class="filter-bar"><div class="search-field"><?= icon('search',18) ?><label class="sr-only" for="card-query">Search cards in this deck</label><input id="card-query" name="q" type="search" maxlength="200" placeholder="Find a question or answer" value="<?= e($query) ?>"></div><button class="btn btn-secondary" type="submit">Search cards</button><?php if ($query !== ''): ?><a href="<?= e(url('/decks/' . ((int) $deck['id']))) ?>" class="text-link">Clear</a><?php endif; ?></form>
<?php if (!$cards): ?><div class="empty-state"><span class="empty-icon"><?= icon('cards',34) ?></span><h3><?= $query !== '' ? 'No matching flashcards' : 'Your next discovery starts here' ?></h3><p><?= $query !== '' ? 'Try a different phrase, or clear the search to see every card.' : 'Add your first question and answer. Small, focused cards make for a calmer study session.' ?></p><a class="btn btn-primary" href="<?= e(url($query !== '' ? '/decks/'.(int)$deck['id'] : '/decks/'.(int)$deck['id'].'/cards/create')) ?>"><?= $query !== '' ? 'Show all cards' : 'Add your first card' ?></a></div><?php else: ?><ol class="card-list"><?php foreach ($cards as $index => $card): ?><li class="flashcard-row"><span class="card-index"><?= str_pad((string)($index+1),2,'0',STR_PAD_LEFT) ?></span><div class="card-copy"><span class="study-label">QUESTION</span><h3><?= nl2br(e($card['question'])) ?></h3><details><summary>View answer</summary><div class="card-back"><p><?= nl2br(e($card['answer'])) ?></p><?php if ($card['explanation'] !== ''): ?><p class="muted"><?= nl2br(e($card['explanation'])) ?></p><?php endif; ?></div></details><div class="card-schedule"><span class="badge"><?= e(ucfirst(str_replace('_',' ',$card['review_state'] ?? 'new'))) ?></span><span><?= (int) ($card['total_reviews'] ?? 0) ?> reviews · Due <?= e(format_date($card['due_at'],'M j, H:i')) ?> UTC</span></div></div><div class="card-actions"><a href="<?= e(url('/cards/' . ((int) $card['id']) . '/edit')) ?>" class="btn btn-ghost btn-small" aria-label="Edit flashcard <?= $index+1 ?>"><?= icon('edit',17) ?><span>Edit</span></a><a href="<?= e(url('/cards/' . ((int) $card['id']) . '/delete')) ?>" class="btn btn-ghost btn-small danger-text" aria-label="Delete flashcard <?= $index+1 ?>"><?= icon('trash',17) ?><span>Delete</span></a></div></li><?php endforeach; ?></ol><?php endif; ?></section>
<div class="deck-bottom-meta"><span>Created <?= e(format_date($deck['created_at'])) ?> · Updated <?= e(format_date($deck['updated_at'])) ?></span><a class="text-link danger-text" href="<?= e(url('/decks/' . ((int) $deck['id']) . '/delete')) ?>"><?= icon('trash',16) ?> Delete this deck</a></div>
